import json
import unittest

from handoff_demo.cursor import encode_cursor


class HiddenTests(unittest.TestCase):
    def test_current_generation_applies_to_every_token(self):
        for token in ("next", "", "a&b", "é/中"):
            with self.subTest(token=token):
                encoded = encode_cursor(token)
                try:
                    payload = json.loads(encoded)
                except (json.JSONDecodeError, TypeError) as error:
                    self.fail(f"expected a current JSON cursor payload: {error}")
                self.assertEqual(payload, {"cursor": token, "version": 2})
                self.assertIs(type(payload["version"]), int)


if __name__ == "__main__":
    unittest.main()
